import os
import json
import re

def load():
    d = os.environ['RLM_SESSION_DIR']
    path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    content = open(path).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_text = content[m.end():].split('\n')[:h]
        rows = [r.split() for r in rows_text]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

